package edu.ku.commerce.omnichannel_commerce.payment; import jakarta.persistence.*; import lombok.*; import java.math.*;
@Entity @Table(uniqueConstraints=@UniqueConstraint(columnNames={"orderId","idempotencyKey"})) @Getter @Setter @NoArgsConstructor public class Payment { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private Long orderId; private String idempotencyKey; @Enumerated(EnumType.STRING) private Status status; @Column(precision=19,scale=2) private BigDecimal amount; public enum Status { INITIATED, AUTHORIZED, CAPTURED, FAILED, REFUNDED, VOIDED } }
